class Graph:
    def __init__(self, vertices):
        self.V = vertices  # Number of vertices
        self.graph = {}    # Adjacency list representation of the graph

    def add_edge(self, u, v):
        if u in self.graph:
            self.graph[u].append(v)
        else:
            self.graph[u] = [v]

    def dfs(self, start, goal, visited=None):
        if visited is None:
            visited = set()
        if start == goal:
            return [start]

        visited.add(start)

        # Recursively call dfs for each neighbor that hasn't been visited
        for neighbor in self.graph[start]:
            if neighbor not in visited:
                path = self.dfs(neighbor, goal, visited)
                if path:
                    return [start] + path
        return None

