class GridSearch:
    def __init__(self, grid):
        self.grid = grid
        self.rows, self.cols = len(grid), len(grid[0])
        self.visited = set()

    def find_path(self, start, end):
        if start == end:
            return [start]

        queue = collections.deque([start])
        visited = set([start])

        while queue:
            current = queue.popleft()
            if current == end:
                return self.reconstruct_path(start, end)

            for dx, dy in [(0, 1), (1, 0), (0, -1), (-1, 0)]:
                next_pos = (current[0] + dx, current[1] + dy)
                if 0 <= next_pos[0] < self.rows and 0 <= next_pos[1] < self.cols and next_pos not in visited:
                    visited.add(next_pos)
                    queue.append(next_pos)

        return None

    def reconstruct_path(self, start, end):
        path = []
        current = end
        while current != start:
            path.append(current)
            for dx, dy in [(0, 1), (1, 0), (0, -1), (-1, 0)]:
                next_pos = (current[0] - dx, current[1] - dy)
                if self.grid[next_pos[0]][next_pos[1]] == 1 and next_pos in self.visited:
                    current = next_pos
                    break
        path.append(start)
        path.reverse()
        return path

def create_grid(rows, cols):
    grid = [[0] * cols for _ in range(rows)]
    return grid

