import heapq

def heuristic(a, b):
    # Euclidean distance heuristic
    return ((b[0] - a[0]) ** 2 + (b[1] - a[1]) ** 2) ** 0.5

def astar(graph, start, end):
    if start == end:
        return [start]

    # Priority queue to select the vertex with the lowest `f` score
    pq = [(0, start)]
    # Dictionary to keep track of the cost from start to each vertex
    costs = {start: 0}
    # Dictionary to keep track of the parent vertex for each vertex
    parents = {start: None}
    # Dictionary to keep track of the best path found so far to each vertex
    best_paths = {start: [start]}

    while pq:
        current_cost, current_vertex = heapq.heappop(pq)

        if current_vertex == end:
            return best_paths[end]

        for neighbor, edge_cost in graph[current_vertex].items():
            new_cost = costs[current_vertex] + edge_cost

            if neighbor not in costs or new_cost < costs[neighbor]:
                costs[neighbor] = new_cost
                priority = new_cost + heuristic(end, neighbor)
                heapq.heappush(pq, (priority, neighbor))
                parents[neighbor] = current_vertex
                best_paths[neighbor] = best_paths[current_vertex] + [neighbor]

    return None

